-- SQL Server 2017+. Dedicated practice database ONLY; drops matching tables.
SET NOCOUNT ON;
DROP TABLE IF EXISTS dbo.WIDE_COUNTS;
DROP TABLE IF EXISTS dbo.ENROLL;
DROP TABLE IF EXISTS dbo.ORDERS;
DROP TABLE IF EXISTS dbo.PLAYER;
DROP TABLE IF EXISTS dbo.FK_LAB;
DROP TABLE IF EXISTS dbo.COURSE;
DROP TABLE IF EXISTS dbo.STUDENT;
DROP TABLE IF EXISTS dbo.TEAM;
DROP TABLE IF EXISTS dbo.DEPT;
DROP TABLE IF EXISTS dbo.CUSTOMER;
DROP TABLE IF EXISTS dbo.DDL_LAB;
CREATE TABLE dbo.TEAM (TEAM_ID VARCHAR(4) PRIMARY KEY, TEAM_NAME VARCHAR(30) NOT NULL);
CREATE TABLE dbo.DEPT (DEPT_ID INT PRIMARY KEY, DEPT_NAME VARCHAR(30) NOT NULL);
CREATE TABLE dbo.PLAYER (PLAYER_ID INT PRIMARY KEY, TEAM_ID VARCHAR(4) NOT NULL REFERENCES dbo.TEAM(TEAM_ID), PLAYER_NAME VARCHAR(30) NOT NULL, POSITION VARCHAR(2) NULL, SALARY DECIMAL(10,0) NOT NULL, HIRE_DATE DATE NOT NULL, MANAGER_ID INT NULL, BONUS DECIMAL(10,0) NULL, ACTIVE_YN CHAR(1) NOT NULL, DEPT_ID INT NULL REFERENCES dbo.DEPT(DEPT_ID), CONSTRAINT FK_PLAYER_MANAGER FOREIGN KEY (MANAGER_ID) REFERENCES dbo.PLAYER(PLAYER_ID), CONSTRAINT CK_PLAYER_PAY CHECK (SALARY>=0));
CREATE TABLE dbo.CUSTOMER (CUSTOMER_ID INT PRIMARY KEY, CUSTOMER_NAME VARCHAR(30) NOT NULL, REGION VARCHAR(20));
CREATE TABLE dbo.ORDERS (ORDER_ID INT PRIMARY KEY, CUSTOMER_ID INT NOT NULL REFERENCES dbo.CUSTOMER(CUSTOMER_ID), ORDER_DATE DATE NOT NULL, AMOUNT DECIMAL(10,0) NOT NULL, STATUS VARCHAR(12) NOT NULL);
CREATE TABLE dbo.STUDENT (STUDENT_ID INT PRIMARY KEY, STUDENT_NAME VARCHAR(30));
CREATE TABLE dbo.COURSE (COURSE_ID INT PRIMARY KEY, COURSE_NAME VARCHAR(30));
CREATE TABLE dbo.ENROLL (ENROLL_ID INT PRIMARY KEY, STUDENT_ID INT NOT NULL REFERENCES dbo.STUDENT(STUDENT_ID), COURSE_ID INT NOT NULL REFERENCES dbo.COURSE(COURSE_ID), SCORE INT, CONSTRAINT UQ_ENROLL UNIQUE(STUDENT_ID,COURSE_ID));
CREATE TABLE dbo.WIDE_COUNTS (TEAM_ID VARCHAR(4) PRIMARY KEY, FW INT, MF INT);
